parameters.jsCode:
// Capturamos los elementos recibidos del AI Agent
const items = $input.all();
const results = [];

for (const item of items) {
  let outputRaw = item.json.output || "";
  let jsonParsed = null;

  if (typeof outputRaw === 'string') {
    // 1. Limpiamos caracteres de formato, saltos de línea y Markdown (```json ... ```)
    let cleanedString = outputRaw
      .replace(/```json/gi, '')
      .replace(/```/g, '')
      .replace(/\\n/g, ' ')
      .replace(/\n/g, ' ')
      .trim();

    // 2. Intentamos parsear la cadena limpia
    try {
      jsonParsed = JSON.parse(cleanedString);
    } catch (e) {
      // Si falla, extraemos únicamente el contenido entre llaves { ... } con Regex
      const jsonMatch = cleanedString.match(/\{[\s\S]*\}/);
      if (jsonMatch) {
        try {
          jsonParsed = JSON.parse(jsonMatch[0]);
        } catch (err) {
          jsonParsed = null;
        }
      }
    }
  } else if (typeof outputRaw === 'object' && outputRaw !== null) {
    jsonParsed = outputRaw;
  }

  // 3. Estructuramos la salida sin errores de sintaxis
  if (jsonParsed) {
    results.push({
      json: {
        categoria: jsonParsed.categoria || "Spam",
        nombre_cliente: jsonParsed.nombre_cliente || "Desconocido",
        resumen_problema: jsonParsed.resumen_problema || outputRaw
      }
    });
  } else {
    results.push({
      json: {
        categoria: "Spam",
        nombre_cliente: "Desconocido",
        resumen_problema: typeof outputRaw === 'string' ? outputRaw.trim() : "Correo procesado"
      }
    });
  }
}

return results;

